  JSONObject all=disk.optJSONObject("completion");if(all==null)all=new JSONObject();String xuid=account.getString("xuid");JSONObject own=all.optJSONObject(xuid);if(own==null)own=new JSONObject();own.put(title,new JSONObject().put("mythic",mythic).put("total",rows.length()));all.put(xuid,own);disk.put("completion",all);
