 void verifyTransfer(JSONObject qr)throws Exception{if(queueRunning||spoofRunning)throw new Exception("Pause sessions before syncing.");JSONObject t=Core.openTransfer(Core.un64(qr.getString("file")),qr.getString("key"),System.currentTimeMillis()/1000);boolean only=Core.eventOnly(t);if(only&&(account==null||!account.getString("xuid").equals(t.getString("xuid"))))throw new Exception("Sign in to the same Xbox account before event-only import.");JSONObject verified=Net.connect(only?auth().getString("authorization"):t.getString("authorization"));if(!verified.getString("xuid").equals(t.getString("xuid")))throw new Exception("Transferred account identity mismatch.");verified.put("eventToken",t.optString("eventToken")).put("eventOnly",only).put("expiresAt",t.getLong("expiresAt")).put("authorizationExpiresAt",t.optString("authorizationExpiresAt")).put("loginProfile","PC transfer");pending=verified;notice="Verified "+verified.getString("gamertag")+". Confirm the import.";}
 void pause(){queueRunning=false;nextAt=0;if(queueJob!=null)queueJob.cancel(true);try{save();}catch(Exception ignored){}}
 void keepAwake(){runOnUiThread(()->{if(queueRunning||spoofRunning)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);});}
 void startQueue()throws Exception{if(queueRunning||!foreground||queue.length()==0)throw new Exception("Load a queue and keep the app open.");auth();queueRunning=true;keepAwake();queueJob=sessions.submit(()->{try{for(int i=0;i<queue.length()&&queueRunning&&foreground;i++){JSONObject item=queue.getJSONObject(i);String status=item.optString("status","Waiting");if(status.startsWith("Accepted")||status.startsWith("Already"))continue;try{item.put("status","Waiting");long seconds=Math.max(0,Math.min(31536000,item.optLong("delay",60)));nextAt=System.currentTimeMillis()+seconds*1000;save();push();Thread.sleep(seconds*1000);if(!queueRunning||!foreground)break;JSONObject game=item.getJSONObject("game"),row=selectRow(rows(game,auth().getString("xuid")),item.getString("achievementId"));if(unlocked(row)){item.put("status","Already unlocked");save();continue;}item.put("status","Submitting");save();send(game,row);item.put("status","Accepted — verify progress");save();}catch(InterruptedException e){if(item.optString("status").equals("Submitting"))item.put("status","Interrupted — refresh before retry");break;}catch(Exception e){item.put("status","Failed: "+safe(e));save();if(prefs.optBoolean("stopOnFailure",true)){notifyUser("Auto Unlock paused",safe(e));break;}}}boolean done=true;for(int x=0;x<queue.length();x++){String st=queue.getJSONObject(x).optString("status");if(!st.startsWith("Accepted")&&!st.startsWith("Already"))done=false;}if(done&&prefs.optBoolean("notifyComplete",true))notifyUser("Auto Unlock finished","Refresh achievements to verify accepted requests.");}catch(Exception e){notice=safe(e);}finally{queueRunning=false;nextAt=0;keepAwake();try{save();}catch(Exception ignored){}push();}});}
 void startSpoof(String title)throws Exception{if(spoofRunning)throw new Exception("Stop the current spoof first.");Core.numeric(title);auth();spoofRunning=true;spoofTitle=title;spoofStatus="Sending heartbeat…";keepAwake();spoofJob=sessions.submit(()->{try{while(spoofRunning&&foreground){Net.presence(auth(),title);if(spoofStarted==0)spoofStarted=System.currentTimeMillis();spoofStatus="Heartbeat accepted";push();Thread.sleep(240000);}}catch(InterruptedException ignored){}catch(Exception e){spoofStatus=safe(e);if(prefs.optBoolean("stopOnSpoofFailure",true))pause();if(prefs.optBoolean("notifySpoofFailure",true))notifyUser("Title spoofing stopped",spoofStatus);}finally{spoofRunning=false;spoofStarted=0;keepAwake();push();}});}
